DISP = {"ipo_listed", "majority_disposed", "partial_sale"}
def counts(events, period):
    oc = collections.Counter(e.get("outcome") for e in events); n = len(events)
    disp = sum(oc[k] for k in DISP); ret = oc["retained_100"]; other = sum(v for k, v in oc.items() if k in ("merged_back_into_parent", "liquidated")); unres = n - disp - ret - other
    mk = md[(md.period == period) & (md.type == "carve_out")]; ok = mk[mk.status == "ok"]
    o = own[(own.period == period) & (~own.disagree.astype(bool))]
    sc = set(k for k in (AN_SCORES.get(period) or [])) if False else None
    return {"n": n, "disposed": disp, "retained": ret, "other": other, "unresolved": unres, "priced": int(len(ok)), "priced_1y": int((ok.n_post_days >= 226).sum()), "ownership": int(len(o))}
