             ("SpearmanScoreBhar", r(SP[M]["rho"])), ("SpearmanScoreBharP", p(SP[M]["p"])), ("SpearmanWithinYear", r(SP[M]["rho_within_year_ranks"])), ("SpearmanWithinYearP", p(SP[M]["p_within_year_ranks"])),
