        f"\\quad late $-$ never & & {pct(T['comparisons']['late_ge2y_vs_never']['diff'], 1, True)} & & & \\\\", f"\\quad Welch $p$; Mann--Whitney $p$ & & & {p(T['comparisons']['late_ge2y_vs_never']['welch_p'])} & {p(T['comparisons']['late_ge2y_vs_never']['mannwhitney_p'])} & \\\\",
